integrityCase('worker-bootstrap-names',function(){$r=new ReflectionMethod(O\AssignmentOrderOriginalVerificationWorkerBootstrap::class,'run');assertSameValue(['configJsonPath','commandReadFd','barrierReadFd','barrierWriteFd','resultWriteFd'],array_map(fn($p)=>$p->name,$r->getParameters()),'exact bootstrap names');assertSameValue([true,'int'],[$r->isStatic(),(string)$r->getReturnType()],'run signature');});
integrityCase('worker-stream-interface',function(){assertSameValue(true,interface_exists(O\AssignmentOrderOriginalByteStreamFactory::class),'factory interface');$r=new ReflectionMethod(O\AssignmentOrderOriginalByteStreamFactory::class,'fromBase64');assertSameValue([false,'base64','string',O\AssignmentOrderOriginalByteStream::class],[$r->isStatic(),$r->getParameters()[0]->name,(string)$r->getParameters()[0]->getType(),(string)$r->getReturnType()],'factory exact signature');});
foreach(['Zg=='=>'f','AAH/' => "\x00\x01\xff",''=>''] as $base64=>$bytes)integrityCase('worker-decode-'.bin2hex($base64),function()use($base64,$bytes){$factory=new O\AssignmentOrderOriginalBase64StreamFactory();assertSameValue(true,$factory instanceof O\AssignmentOrderOriginalByteStreamFactory,'declared port implementation');$s=$factory->fromBase64(base64:$base64);try{$r=$s->read(65536);assertSameValue([$bytes===''?'eof':'bytes',$bytes],[$r->status->value,$r->bytes],'independent literal payload');if($bytes!=='')assertSameValue('eof',$s->read(65536)->status->value,'exact EOF');}finally{$s->close();}});
foreach(['Zg','Zg===',"Zg==\n",'Zg-_','Zh==','AA=A','A==='] as $base64)integrityCase('worker-invalid-'.bin2hex($base64),function()use($base64){$caught=null;try{(new O\AssignmentOrderOriginalBase64StreamFactory())->fromBase64($base64);}catch(Throwable $e){$caught=$e;}assertSameValue(true,$caught instanceof InvalidArgumentException,'strict decode rejected');assertSameValue(['Invalid worker base64.',0,null],[$caught->getMessage(),$caught->getCode(),$caught->getPrevious()],'fixed invalid decode');});
integrityCase('worker-oversize-reaches-application',function(){$factory=new O\AssignmentOrderOriginalBase64StreamFactory();$s=$factory->fromBase64(base64_encode(str_repeat('a',20971521)));$n=0;try{do{$r=$s->read(65536);$n+=strlen($r->bytes);assertSameValue(true,strlen($r->bytes)<=65536,'bounded stream chunk');}while($r->status===O\AssignmentOrderOriginalStreamReadStatus::BYTES);assertSameValue(['eof',20971521],[$r->status->value,$n],'transport retains 20MiB+1');}finally{$s->close();}});
foreach(['stream_read','stream_close'] as $fault)integrityCase('worker-stream-fault-'.$fault,function()use($fault){$s=(new O\AssignmentOrderOriginalBase64StreamFactory(new O\AssignmentOrderOriginalWorkerFaults(O\AssignmentOrderOriginalFaultPoint::from($fault))))->fromBase64('Zg==');if($fault==='stream_read'){assertSameValue('failed',$s->read(10)->status->value,'original stream fault preserved');$s->close();}else{$caught=false;try{$s->close();}catch(Throwable){$caught=true;}assertSameValue(true,$caught,'close fault preserved');$s->close();}});
$reads=[['request_lookup','findTerminalRequest',['00000000-0000-4000-8000-000000000901']],['fingerprint_lookup','findAcceptedFingerprint',[str_repeat('a',64)]],['lineage_lookup','findLineage',['original-0090']],['lineage_lookup','findLineageForAssignmentOrder',[4512,81]],['lineage_lookup','findLineageForRevision',['revision-0090']]];
foreach($reads as [$point,$method,$args])integrityCase('worker-lookup-'.$method,function()use($point,$method,$args){$target=O\AssignmentOrderOriginalFaultPoint::tryFrom($point);assertSameValue(true,$target!==null,'declared fault point');$db=new S\OriginalIntegrityNoSql();$observer=new class implements O\AssignmentOrderOriginalPersistenceObserver{public array $calls=[];public function observe(O\AssignmentOrderOriginalPersistenceEvent $event):void{$this->calls[]=$event;}};$repo=new O\AssignmentOrderOriginalMariaDbRepository($db,'p_',new O\AssignmentOrderOriginalWorkerFaults($target),$observer);$r=$repo->$method(...$args);assertSameValue('unavailable',$r->status()->value,'typed unavailable');assertSameValue([],$db->calls,'fault before native SQL');assertSameValue([],$observer->calls,'fault before persistence observer');if(method_exists($r,'result'))assertSameValue(null,$r->result(),'no result payload');else assertSameValue([null,null],[$r->rootOriginalId(),$r->currentRevisionId()],'no lineage metadata');});
foreach([null,'lineage_lookup'] as $point)A::case('worker-native-control-'.($point??'none'),function($f)use($point){$target=$point===null?null:O\AssignmentOrderOriginalFaultPoint::tryFrom($point);if($point!==null)assertSameValue(true,$target!==null,'unrelated declared target');$repo=new O\AssignmentOrderOriginalMariaDbRepository($f->db,$f->prefix,new O\AssignmentOrderOriginalWorkerFaults($target));assertSameValue('not_found',$repo->findTerminalRequest('00000000-0000-4000-8000-000000000901')->status()->value,'no/unrelated fault allows genuine miss');});
